 const expected={version:'dpi-side-compact-conjunction-v24-calibration-v1',inputSha256:SELECTED_V6_SHA,sourceProtocol:'dpi-side-selected-semantic6-v1',protocol:candidate.VERSION,candidatePath:COMPACT_CONJUNCTION_V9_PATH,candidateSha256:pins.get(COMPACT_CONJUNCTION_V9_PATH),baseProtocol:base.VERSION,baseCandidatePath:CONJUNCTION_V8_PATH,baseCandidateSha256:pins.get(CONJUNCTION_V8_PATH),contextTokens:20480,providerTimeoutMs:180000,transportTimeoutMs:180000,reusedCorpus:true,changedProtocol:true,labelsExternal:true,actorProof:false,creditProof:false};
 assert.deepEqual(manifest.sideCompactAdmission,expected);
 assert.equal(manifest.regressionAdmission,undefined);
